export async function createScene(engine, canvas, BABYLON) {
  var scene = new BABYLON.Scene(engine);
  scene.clearColor = BABYLON.Color4.FromHexString("#180825FF");

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0.07, 1.14, 0.06));
  camera.alpha = 2.188;
  camera.beta = 1.035;
  camera.radius = 21;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  // camera.zoomToMouseLocation = true;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.7;

  const meshes = [];
  // let scanSpeed = 1;
  let scanIntensity = 0.8;
  let scanColor = new BABYLON.Color3(0.34, 0.24, 0.75).toLinearSpace().toHexString();
  let scanOrigin = 0;
  let scanActive = false;
  let scanStartTime = null;

  scene.onPointerDown = function (evt, pickResult) {
    if (pickResult.hit) {
      scanOrigin = pickResult.pickedPoint.z;
      scanStartTime = Date.now();
      scanActive = true;
    }
  };

  BABYLON.Effect.ShadersStore["scanningVertexShader"] = `
        precision highp float;
        attribute vec3 position;
        attribute vec3 normal;
        uniform mat4 worldViewProjection;
        uniform mat4 world;
        varying vec3 vWorldPosition;
        varying vec3 vNormal;
        void main() {
            vec4 worldPos = world * vec4(position, 1.0);
            vWorldPosition = worldPos.xyz;
            vNormal = normalize((world * vec4(normal, 0.0)).xyz);
            gl_Position = worldViewProjection * vec4(position, 1.0);
        }
    `;

  BABYLON.Effect.ShadersStore["scanningFragmentShader"] = `
        precision highp float;
        uniform float scanPosition;
        uniform float scanIntensity;
        uniform vec3 scanColor;
        varying vec3 vWorldPosition;
        varying vec3 vNormal;
        void main() {
            float distanceToScan = abs(vWorldPosition.z - scanPosition);
            float scanWidth = 1.0;
            float scanEffect = 1.0 - smoothstep(0.0, scanWidth, distanceToScan);
            scanEffect = pow(scanEffect, 2.0);
            float scanLine = 1.0 - smoothstep(0.0, 0.2, distanceToScan);
            scanLine = pow(scanLine, 3.0);
            vec3 finalColor = scanColor * (scanEffect * scanIntensity + scanLine * 1.5);
            gl_FragColor = vec4(finalColor, scanEffect);
        }
    `;

  BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "undead_house.glb").then((result) => {
    let rootMesh = result.meshes[0];

    rootMesh.getChildMeshes().forEach((m) => {
      meshes.push(m);
    });

    rootMesh.getChildMeshes().forEach((mesh) => {
      if (mesh.material && mesh.material instanceof BABYLON.PBRMaterial) {
        const original = mesh.material;

        const customMaterial = new BABYLON.CustomMaterial("customMaterial", scene);
        customMaterial.diffuseTexture = original.albedoTexture;
        customMaterial.diffuseColor = original.albedoColor;
        customMaterial.emissiveColor = original.emissiveColor;
        customMaterial.bumpTexture = original.bumpTexture;
        customMaterial.specularPower = 64;

        // Fresnel 추가
        customMaterial.Fragment_Before_FragColor(`
                vec3 fresnelColor = vec3(0.2, 0.8, 1.0);  // 밝은 청록색
                float fresnelTerm = pow(1.0 - dot(viewDirectionW, vNormalW), 3.0);
                fresnelTerm = clamp(fresnelTerm * 0.8, 0.0, 1.0); // 강도 조절

                color.rgb = mix(color.rgb, fresnelColor, fresnelTerm);
            `);

        mesh.material = customMaterial;
      }
    });

    // Create shader material
    const scanningMaterial = new BABYLON.ShaderMaterial(
      "scanMat",
      scene,
      {
        vertex: "scanning",
        fragment: "scanning",
      },
      {
        attributes: ["position", "normal"],
        uniforms: ["world", "worldViewProjection", "scanPosition", "scanIntensity", "scanColor"],
        needAlphaBlending: true,
      }
    );

    scanningMaterial.backFaceCulling = false;
    scanningMaterial.alphaMode = BABYLON.Engine.ALPHA_ADD;
    scanningMaterial.zOffset = -10;

    // Clone meshes and apply scan material
    const overlayClones = meshes.map((original) => {
      const clone = original.clone(original.name + "_scan");
      clone.material = scanningMaterial;
      clone.isPickable = false;
      return clone;
    });

    // Animate scan according to the time
    // const startTime = Date.now();
    // scene.registerBeforeRender(() => {
    //     const t = (Date.now() - startTime) / 1000;
    //     const scanY = Math.sin(t * scanSpeed) * 3;
    //     const r = parseInt(scanColor.slice(1, 3), 16) / 255;
    //     const g = parseInt(scanColor.slice(3, 5), 16) / 255;
    //     const b = parseInt(scanColor.slice(5, 7), 16) / 255;
    //     scanningMaterial.setFloat("scanPosition", scanY);
    //     scanningMaterial.setFloat("scanIntensity", scanIntensity);
    //     scanningMaterial.setVector3("scanColor", new BABYLON.Vector3(r, g, b));
    // });

    // Animate scan according to the click
    scene.registerBeforeRender(() => {
      if (!scanActive) return;

      const t = (Date.now() - scanStartTime) / 1000;
      const scanZ = scanOrigin + t * -5;

      const r = parseInt(scanColor.slice(1, 3), 16) / 255;
      const g = parseInt(scanColor.slice(3, 5), 16) / 255;
      const b = parseInt(scanColor.slice(5, 7), 16) / 255;

      scanningMaterial.setFloat("scanPosition", scanZ);
      scanningMaterial.setFloat("scanIntensity", scanIntensity);
      scanningMaterial.setVector3("scanColor", new BABYLON.Vector3(r, g, b));
    });

    var advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

    var panel = new BABYLON.GUI.StackPanel();
    panel.width = "200px";
    panel.isVertical = true;
    panel.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_RIGHT;
    panel.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;
    advancedTexture.addControl(panel);

    var textBlock = new BABYLON.GUI.TextBlock();
    textBlock.text = "color";
    textBlock.color = "white";
    textBlock.height = "30px";
    panel.addControl(textBlock);

    var picker = new BABYLON.GUI.ColorPicker();
    picker.value = BABYLON.Color3.FromHexString(scanColor);
    picker.height = "150px";
    picker.width = "150px";
    picker.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_CENTER;
    picker.onValueChangedObservable.add(function (value) {
      scanColor = value.toHexString();
    });

    panel.addControl(picker);

    // const dpp = new BABYLON.DefaultRenderingPipeline("dpp", true, scene);
    // dpp.imageProcessingEnabled = false;
    // dpp.bloomEnabled = true;
    // dpp.glowLayerEnabled = true;
  });

  return scene;
}
